solutions.naive:
class Solution:
    def longestCycle(self, edges: list[int]) -> int:
        n = len(edges)
        ans = -1
        for s in range(n):
            pos = {}
            u = s
            step = 0
            while u != -1 and u not in pos and step <= n:
                pos[u] = step
                step += 1
                u = edges[u]
            if u in pos:
                ans = max(ans, step - pos[u])
        return ans

