class Solution:
    def longestCycle(self, edges: list[int]) -> int:
        from collections import deque
        n = len(edges)
        indeg = [0] * n
        for v in edges:
            if v != -1:
                indeg[v] += 1
        q = deque([i for i in range(n) if indeg[i] == 0])
        removed = [False] * n
        while q:
            u = q.popleft(); removed[u] = True
            v = edges[u]
            if v != -1:
                indeg[v] -= 1
                if indeg[v] == 0:
                    q.append(v)
        seen = [False] * n
        ans = -1
        for i in range(n):
            if not removed[i] and not seen[i]:
                cur = i; length = 0
                while not seen[cur]:
                    seen[cur] = True; length += 1; cur = edges[cur]
                ans = max(ans, length)
        return ans

