class Solution:
    def longestCycle(self, edges: list[int]) -> int:
        n = len(edges)
        seen = [0] * n
        time = 1
        ans = -1
        for i in range(n):
            if seen[i]:
                continue
            start = time
            u = i
            while u != -1 and seen[u] == 0:
                seen[u] = time
                time += 1
                u = edges[u]
            if u != -1 and seen[u] >= start:
                ans = max(ans, time - seen[u])
        return ans

